package dev.atmcompanion.planning;

import org.junit.jupiter.api.Test;
import java.util.Arrays;
import java.util.Collections;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotSame;

public class PlanResultTest {

    @Test
    public void testWithLimitations() {
        // Create an initial PlanResult instance
        PlanResult initialPlanResult = new PlanResult(Collections.singletonList("initialLimitation"));

        // Define new limitations
        List<String> newLimitations = Arrays.asList("newLimitation1", "newLimitation2");

        // Create a new PlanResult instance with updated limitations
        PlanResult updatedPlanResult = initialPlanResult.withLimitations(newLimitations);

        // Verify that the new instance is not the same as the initial instance
        assertNotSame(initialPlanResult, updatedPlanResult);

        // Verify that the new instance has the updated limitations
        assertEquals(newLimitations, updatedPlanResult.getLimitations());

        // Verify that other components are preserved
        assertEquals(initialPlanResult.getOtherComponent(), updatedPlanResult.getOtherComponent());
    }

}
